package org.apache.commons.compress.archivers.ar;

import java.io.*;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.ar.ArArchiveInputStream;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ArArchiveInputStream_close_TriageGen2Test {

    @Test
    public void testClose_FirstTime_ClosesInput() throws IOException {
        // Arrange
        InputStream mockInput = mock(InputStream.class);
        ArArchiveInputStream inputStream = new ArArchiveInputStream(mockInput);

        // Act
        inputStream.close();

        // Assert
        verify(mockInput, times(1)).close();
    }

    @Test
    public void testClose_SecondTime_DoesNotCloseInputAgain() throws IOException {
        // Arrange
        InputStream mockInput = mock(InputStream.class);
        ArArchiveInputStream inputStream = new ArArchiveInputStream(mockInput);

        // Act
        inputStream.close(); // First call: closed becomes true
        inputStream.close(); // Second call: closed is already true, should skip

        // Assert
        verify(mockInput, times(1)).close();
    }

    @Test
    public void testClose_ThrowsException_PropagatesException() throws IOException {
        // Arrange
        InputStream mockInput = mock(InputStream.class);
        doThrow(new IOException("Simulated close failure")).when(mockInput).close();
        ArArchiveInputStream inputStream = new ArArchiveInputStream(mockInput);

        // Act & Assert
        try {
            inputStream.close();
            org.junit.Assert.fail("Expected IOException to be thrown");
        } catch (IOException e) {
            org.junit.Assert.assertEquals("Simulated close failure", e.getMessage());
        }

        // Verify that even if exception is thrown, the state might be problematic 
        // depending on implementation, but based on provided code, 'closed' is set to true BEFORE close().
        // We test that the exception propagates.
    }
}
